  ///  Magnetospheric structures (tori, moon sweep gaps, ring absorption, slot region).
  public var STRUCTURES: FlatbufferVector<RBFStructureFeature> { return _accessor.vector(at: VT.STRUCTURES, byteSize: 4) }
  ///  Computed anomaly contours (e.g. South Atlantic Anomaly at reference altitudes).
  public var SAA_CONTOURS: FlatbufferVector<RBFSaaContour> { return _accessor.vector(at: VT.SAA_CONTOURS, byteSize: 4) }
  ///  Referenced $SWS or $SPW space-weather record identifiers.
  public var SPACE_WEATHER_REFS: FlatbufferVector<String?> { return _accessor.vector(at: VT.SPACE_WEATHER_REFS, byteSize: 4) }
  ///  Record-level source and build provenance.
  public var PROVENANCE: PVN! { let o = _accessor.offset(VT.PROVENANCE); return PVN(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public static func startRBF(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 28) }
