  public static func createRBF(
    _ fbb: inout FlatBufferBuilder,
    RBF_IDOffset RBF_ID: Offset,
    BODY_NAMEOffset BODY_NAME: Offset,
    BODY_NAIF_ID: Int32 = 0,
    MODEL: rbfModelKind = .unspecified,
    MODEL_VERSIONOffset MODEL_VERSION: Offset = Offset(),
    MAG_MODEL_IDOffset MAG_MODEL_ID: Offset = Offset(),
    REFERENCE_FRAMEOffset REFERENCE_FRAME: Offset = Offset(),
    SPECIES: rbfParticleSpecies = .unspecified,
    FLUX_TYPE: rbfFluxKind = .unspecified,
    UNITSOffset UNITS: Offset,
    EPOCHOffset EPOCH: Offset,
    KP: Double = 0.0,
    HAS_KP: Bool = false,
    DST_NT: Double = 0.0,
    HAS_DST_NT: Bool = false,
    F107: Double = 0.0,
    HAS_F107: Bool = false,
    SOLAR_WIND_PRESSURE_NPA: Double = 0.0,
    HAS_SOLAR_WIND_PRESSURE: Bool = false,
    QUANTILE_PCT: Double = 50.0,
    L_SHELLSVectorOffset L_SHELLS: Offset = Offset(),
    ENERGY_MEVVectorOffset ENERGY_MEV: Offset = Offset(),
    B_OVER_B0VectorOffset B_OVER_B0: Offset = Offset(),
    FLUX_GRIDVectorOffset FLUX_GRID: Offset = Offset(),
    STRUCTURESVectorOffset STRUCTURES: Offset = Offset(),
    SAA_CONTOURSVectorOffset SAA_CONTOURS: Offset = Offset(),
    SPACE_WEATHER_REFSVectorOffset SPACE_WEATHER_REFS: Offset = Offset(),
    PROVENANCEOffset PROVENANCE: Offset
  ) -> Offset {
    let __start = RBF.startRBF(&fbb)
    RBF.add(RBF_ID: RBF_ID, &fbb)
    RBF.add(BODY_NAME: BODY_NAME, &fbb)
    RBF.add(BODY_NAIF_ID: BODY_NAIF_ID, &fbb)
    RBF.add(MODEL: MODEL, &fbb)
    RBF.add(MODEL_VERSION: MODEL_VERSION, &fbb)
    RBF.add(MAG_MODEL_ID: MAG_MODEL_ID, &fbb)
    RBF.add(REFERENCE_FRAME: REFERENCE_FRAME, &fbb)
    RBF.add(SPECIES: SPECIES, &fbb)
    RBF.add(FLUX_TYPE: FLUX_TYPE, &fbb)
    RBF.add(UNITS: UNITS, &fbb)
    RBF.add(EPOCH: EPOCH, &fbb)
    RBF.add(KP: KP, &fbb)
    RBF.add(HAS_KP: HAS_KP, &fbb)
    RBF.add(DST_NT: DST_NT, &fbb)
    RBF.add(HAS_DST_NT: HAS_DST_NT, &fbb)
    RBF.add(F107: F107, &fbb)
    RBF.add(HAS_F107: HAS_F107, &fbb)
    RBF.add(SOLAR_WIND_PRESSURE_NPA: SOLAR_WIND_PRESSURE_NPA, &fbb)
    RBF.add(HAS_SOLAR_WIND_PRESSURE: HAS_SOLAR_WIND_PRESSURE, &fbb)
    RBF.add(QUANTILE_PCT: QUANTILE_PCT, &fbb)
    RBF.addVectorOf(L_SHELLS: L_SHELLS, &fbb)
    RBF.addVectorOf(ENERGY_MEV: ENERGY_MEV, &fbb)
    RBF.addVectorOf(B_OVER_B0: B_OVER_B0, &fbb)
    RBF.addVectorOf(FLUX_GRID: FLUX_GRID, &fbb)
    RBF.addVectorOf(STRUCTURES: STRUCTURES, &fbb)
    RBF.addVectorOf(SAA_CONTOURS: SAA_CONTOURS, &fbb)
    RBF.addVectorOf(SPACE_WEATHER_REFS: SPACE_WEATHER_REFS, &fbb)
    RBF.add(PROVENANCE: PROVENANCE, &fbb)
    return RBF.endRBF(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.RBF_ID, fieldName: "RBF_ID", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.BODY_NAME, fieldName: "BODY_NAME", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.BODY_NAIF_ID, fieldName: "BODY_NAIF_ID", required: false, type: Int32.self)
    try _v.visit(field: VT.MODEL, fieldName: "MODEL", required: false, type: rbfModelKind.self)
    try _v.visit(field: VT.MODEL_VERSION, fieldName: "MODEL_VERSION", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.MAG_MODEL_ID, fieldName: "MAG_MODEL_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.REFERENCE_FRAME, fieldName: "REFERENCE_FRAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.SPECIES, fieldName: "SPECIES", required: false, type: rbfParticleSpecies.self)
    try _v.visit(field: VT.FLUX_TYPE, fieldName: "FLUX_TYPE", required: false, type: rbfFluxKind.self)
    try _v.visit(field: VT.UNITS, fieldName: "UNITS", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.EPOCH, fieldName: "EPOCH", required: true, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.KP, fieldName: "KP", required: false, type: Double.self)
    try _v.visit(field: VT.HAS_KP, fieldName: "HAS_KP", required: false, type: Bool.self)
    try _v.visit(field: VT.DST_NT, fieldName: "DST_NT", required: false, type: Double.self)
    try _v.visit(field: VT.HAS_DST_NT, fieldName: "HAS_DST_NT", required: false, type: Bool.self)
    try _v.visit(field: VT.F107, fieldName: "F107", required: false, type: Double.self)
    try _v.visit(field: VT.HAS_F107, fieldName: "HAS_F107", required: false, type: Bool.self)
    try _v.visit(field: VT.SOLAR_WIND_PRESSURE_NPA, fieldName: "SOLAR_WIND_PRESSURE_NPA", required: false, type: Double.self)
    try _v.visit(field: VT.HAS_SOLAR_WIND_PRESSURE, fieldName: "HAS_SOLAR_WIND_PRESSURE", required: false, type: Bool.self)
    try _v.visit(field: VT.QUANTILE_PCT, fieldName: "QUANTILE_PCT", required: false, type: Double.self)
    try _v.visit(field: VT.L_SHELLS, fieldName: "L_SHELLS", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.ENERGY_MEV, fieldName: "ENERGY_MEV", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.B_OVER_B0, fieldName: "B_OVER_B0", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.FLUX_GRID, fieldName: "FLUX_GRID", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.STRUCTURES, fieldName: "STRUCTURES", required: false, type: ForwardOffset<Vector<ForwardOffset<RBFStructureFeature>, RBFStructureFeature>>.self)
    try _v.visit(field: VT.SAA_CONTOURS, fieldName: "SAA_CONTOURS", required: false, type: ForwardOffset<Vector<ForwardOffset<RBFSaaContour>, RBFSaaContour>>.self)
    try _v.visit(field: VT.SPACE_WEATHER_REFS, fieldName: "SPACE_WEATHER_REFS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.PROVENANCE, fieldName: "PROVENANCE", required: true, type: ForwardOffset<PVN>.self)
    _v.finish()
  }
